import './App.css';
import React, { useEffect } from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import { ProSidebarProvider } from "react-pro-sidebar";
import { useSelector } from "react-redux";
import { reloadUser } from "./redux/slices/userSlice";
import store from "./redux/store";

import Home from "./pages/Home";
import Register from "./pages/Register";
import Login from "./pages/Login";

import Layout from "./admin/global/Layout";
import AdminDashboard from "./admin/Dashboard";
import AdminProfile from "./admin/Profile";
import AdminUsers from "./admin/Users";
import AdminContact from "./admin/Contact";

import NotFound from "./pages/Error";
import ConnectionStatus from "./Components/ConnectionStatus.js";
import ForgotPassword from './pages/ForgotPassword.js';
import ResetPassword from './pages/ResetPassword.js';

function App() {
  const { isAuthenticated, user } = useSelector((state) => state.user);


  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      store.dispatch(reloadUser());
    }
  }, []);
  const AdminDashboardHDC = Layout(AdminDashboard);
  const AdminProfileHDC = Layout(AdminProfile);
  const AdminUsersHDC = Layout(AdminUsers); 
  const AdminContactHDC = Layout(AdminContact);

  
  return (
    <>
      <ConnectionStatus />
      <ProSidebarProvider>
        <BrowserRouter>
          <Routes>
            <Route path="/" element={<Home />} />
            <Route
              path="/dashboard"
              element={
                isAuthenticated ? (
                  user ? (
                    user.role === 0 ? (
                      <Home />
                    ) : user.role >= 1 ? (
                      <AdminDashboardHDC />
                    ) : (
                      <Home /> 
                    )
                  ) : (
                    <Login />
                  )
                ) : (
                  <Login />
                )
              }
            />

            {/* Common Routes  */}
            {/* <Route path="/" element={<Home />} /> */}
            <Route path="/register" element={<Register />} />
            <Route path="/login" element={<Login />} />
            <Route path="/password/forgot" element={<ForgotPassword />} />
            <Route path="/password/reset" element={<ResetPassword />} />

            {/* Admin Routes */}
            {user?.role >= 1 ? (
              <>
                <Route path="/admin/profile" element={<AdminProfileHDC />} />
                <Route path="/admin/users" element={<AdminUsersHDC />} />
                <Route path="/admin/contact" element={<AdminContactHDC />} />
              </>
            ) : null}
            {/* Page not found Route */}
            <Route path="*" element={<NotFound />} />
          </Routes>
        </BrowserRouter>
      </ProSidebarProvider>
    </>
  );
}

export default App;
